guide.simple_bytestorage_scripting.examp:
§eЗабирать из сундука§r
§bvar c = side("up");
function tick() { if (c) c.pull(); }§r

§eКормить группу печей§r
(шины с ID "smelters", печи с их северной стороны)
§bfunction tick() {
  var f = side("north", "smelters");
  if (f) f.push("minecraft:raw_iron", 16);
}§r

§eСобирать со всех сундуков "inbox"§r
§bfunction tick() {
  var i = side("up", "inbox");
  if (i) i.pull();
}§r

§eДве группы§r
§bfunction tick() {
  var a = side("up", "in"), b = side("up", "out");
  if (a && b) a.move(b);
}§r

§eАвтокрафт при нехватке§r
§bfunction tick() {
  if (net.count("minecraft:stick") < 64)
    net.craft("minecraft:stick", 64);
}§r
